-- ============================================================
-- Ozbek2f (6/6) — DB kontentinin UZ tərcüməsi
-- COALESCE + guarded UPDATE — mövcud/əl tərcümələri qorunur (idempotent).
-- Cəmi: 6145 UPDATE (day-notifications İSTİSNA — ayrıca faylda)
-- ƏVVƏL sxem faylı (sütunlar) işlədilməlidir.
-- ============================================================

UPDATE public.pregnancy_daily_content SET baby_development_uz = COALESCE(baby_development_uz, 'Ultratovush tekshiruvida chaqalog‘ingiz skeleti endi aniq ko‘rinadigan darajada rivojlangan. Skelet tizimi suyaklar va ularni birlashtiruvchi bo‘g‘imlardan iborat. Bu suyaklar mushaklar bilan birgalikda ishlab, chaqalog‘ingizning qorningizdagi chaqqon harakatlarini ta’minlaydi.;;;
Yangi tug‘ilgan chaqaloq tanasida 270 ta suyak bo‘lsa, voyaga yetgan insonda bu raqam 206 tani tashkil etadi. Buning sababi shundaki, chaqaloq suyaklari hali tog‘aysimon va bir-biridan alohida bo‘ladi. Bunday egiluvchanlik chaqaloq tug‘ruq yo‘lidan o‘tayotganda jarohatlanishining oldini oladi. Tug‘ilgandan keyin bu kichik suyaklar (masalan, bosh suyagi qismlari) vaqt o‘tishi bilan bir-biriga qo‘shilib, kattaroq va mustahkamroq suyaklarni hosil qiladi.'), baby_message_uz = COALESCE(baby_message_uz, 'Boshimni tik tutyapman! 🦒 Onajon, bo‘yin mushaklarim shu qadar kuchaydiki, endi boshimni tik tuta olaman. Avvallari boshim ko‘ksimga tomon egilib turardi, hozir esa atrofga ancha erkin qaray olaman (garchi bu yer qorong‘i bo‘lsa ham). Tanam uzaymoqda, men yanada nozik va qomatim tik bo‘lib boryapti. Qorningizda gimnastika qilish juda yoqimli!'), baby_size_fruit_uz = COALESCE(baby_size_fruit_uz, 'Avokado'), body_changes_uz = COALESCE(body_changes_uz, 'Homiladorlik davrida gormonal muvozanat o‘zgargani sababli tanangiz odatdagidan boshqacha jarayonlarni boshdan kechiradi. Ayniqsa, homiladorlikning dastlabki uch oyida ko‘ngil aynishi, qusish, ko‘z oldi qorong‘ilashishi, bosh aylanishi va hushdan ketish kabi holatlar tez-tez uchrasa-da, ular homiladorlikning istalgan davrida vaqti-vaqti bilan yuz berishi mumkin. Homiladorlik paytida bachadon odatdagidan ancha kattalashgani uchun tanadagi qonning katta qismi chaqalog‘ingiz joylashgan bachadonga yo‘naladi. Shu sababli ba’zan boshqa a’zolarga, jumladan, miyaga ham kerakli miqdorda qon yetib bormasligi mumkin. Bunday vaziyatda tanangiz qonga bo‘lgan keskin ehtiyojni qondira olmagani sababli bosh aylanishi va hushdan ketish kabi noxush holatlar yuz berishi mumkin. Juda tez va keskin o‘rningizdan turmaslik, chalqancha yotmaslik, och va suvsiz qolmaslik hamda kamqonlik bo‘lsa, uni davolatish bu davrda yuz berishi mumkin bo‘lgan hushdan ketish va bosh aylanishining oldini olishga yordam beradi.'), daily_tip_uz = COALESCE(daily_tip_uz, 'Qorin sohasidagi qichishishni kamaytirish uchun tabiiy yog‘lar bilan uqalashni unutmang. Bel og‘rig‘ining oldini olish uchun uzoq vaqt bir xil holatda o‘tirmaslikka harakat qiling. Yetarli miqdorda suyuqlik ichish sizning ham, chaqalog‘ingizning ham moddalar almashinuvi uchun juda muhim. Kelasi hafta bizni yanada katta kutilmagan yangiliklar kutmoqda!') WHERE id = 'b6a34159-6856-4473-a35e-81785fe0fc0e';

