UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Quyoshda bo‘lish'), description_uz = COALESCE(description_uz, 'Me’yorida quyoshda bo‘lish odatda xavfsiz va D vitamini ishlab chiqarilishiga yordam beradi. Biroq quyoshda uzoq vaqt qolish suvsizlanish, issiq urishi va quyoshda kuyishga olib kelishi mumkin, bu esa noqulaylik tug‘dirishi va salomatlikka zarar yetkazishi mumkin. Bevosita quyosh nurlari ostida bo‘lishni, ayniqsa eng issiq paytda (ertalab soat 10 dan kechki 4 gacha) cheklash, himoya kiyimlarini kiyish, quyoshdan himoyalovchi kremdan foydalanish va ko‘proq suyuqlik ichish tavsiya etiladi.') WHERE id = '3982c1ae-13f7-4142-8726-4f0481aa7c58';
