UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Parvoz'), description_uz = COALESCE(description_uz, 'Tijorat aviakompaniyalari reyslarida uchish odatda homiladorlik davrida xavfsiz hisoblanadi. Biroq, ayniqsa uzoq davom etadigan parvozlardan oldin, homiladorlik bilan bog‘liq hech qanday muammo bo‘lmasa ham, shifokoringiz bilan maslahatlashish tavsiya etiladi. Ko‘p suv iching, qon ivib qolishining oldini olish uchun harakatlanib turing va tavsiya etilsa, kompression paypoqlardan foydalaning. Bu tavsiyalar emizikli onalarga ham tegishli, biroq uzoq parvozlarda chaqaloqni oziqlantirish va uning qulayligi uchun qo‘shimcha tayyorgarlik ko‘rish foydali bo‘lishi mumkin.') WHERE id = 'b0855f6d-792e-4d72-a4d4-3509c5e9f5a1';
UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Losos (Syomga)'), description_uz = COALESCE(description_uz, 'Omega-3 manbai. Haftasiga 2 martagacha, to‘liq pishirilgan holda iste’mol qilish tavsiya etiladi.') WHERE id = 'b0c7bfda-4110-4f88-8a68-a6303d1447c6';
UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Samolyotda uchish'), description_uz = COALESCE(description_uz, 'Tijorat reyslarida uchish odatda homiladorlik davrida xavfsiz hisoblanadi. Ayniqsa uchinchi trimestrda samolyotda uchish haqida shifokoringiz bilan maslahatlashish, qon ivib qolishining oldini olish uchun ko‘p suv ichish va harakatlanib turish tavsiya etiladi. Bu tavsiyalar emizikli onalarga ham tegishli, biroq uzoq parvozlarda chaqaloqni oziqlantirish va uning qulayligi uchun qo‘shimcha tayyorgarlik ko‘rish kerak.') WHERE id = 'b1a7ab3d-fa21-4a98-ae31-159ea5e65822';
UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Sujuk'), description_uz = COALESCE(description_uz, 'Sujukni emizish davrida me’yorida iste’mol qilish odatda xavfsiz, biroq uning tarkibida natriy va yog‘ miqdori yuqori ekanini hisobga olish muhim. Shuningdek, achchiq mahsulotlar ba’zan ona suti orqali chaqaloqqa ta’sir qilib, bezovtalik yoki ovqat hazm qilish muammolariga sabab bo‘lishi mumkin. Chaqalog‘ingizning reaksiyasini kuzating.') WHERE id = 'b4267eb3-6e6a-46f3-93ce-1dab05fea063';
UPDATE public.safety_items SET name_uz = COALESCE(name_uz, 'Tishlarni oqartirish'), description_uz = COALESCE(description_uz, 'Tish milklari sezgir bo‘lgani uchun bu muolajani kechiktirish tavsiya etiladi.') WHERE id = '7d48f86d-1b7b-41b5-a5c1-7596a6ad0774';
