-- ── teething_care_tips → uz (8 sətir) ──
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Toza nam mato'), content_uz = COALESCE(content_uz, 'Toza, nam matoni muzlatkichda sovuting va chaqaloqqa uni chaynashga ruxsat bering.') WHERE id = 'e268d30e-59e5-4d1a-8104-c57c0ead8912';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Milklarni yengil massaj qilish'), content_uz = COALESCE(content_uz, 'Toza barmog‘ingiz bilan chaqalog‘ingizning milklarini aylana harakatlar bilan ohista massaj qiling.') WHERE id = 'e90cc935-e345-454f-84f3-c300a7e97793';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Xavfsiz tish chiqarish o‘yinchoqlari'), content_uz = COALESCE(content_uz, 'BPA saqlamaydigan, zaharli bo‘lmagan tish chiqarish o‘yinchoqlarini tanlang. Bo‘g‘ilish xavfini tug‘dirishi mumkin bo‘lgan mayda qismlari bor o‘yinchoqlardan saqlaning.') WHERE id = '30255b45-90fc-46ab-8b8c-9ce75952377f';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Birinchi tishni parvarishlash'), content_uz = COALESCE(content_uz, 'Birinchi tish ko‘rinishi bilanoq, chaqaloqlar uchun mo‘ljallangan yumshoq tish cho‘tkasi va faqat suv yordamida tishni tozalashni boshlang.') WHERE id = '3fbd0995-1618-49b3-aa8c-f8ff75c52bc6';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Shakardan saqlaning'), content_uz = COALESCE(content_uz, 'Tishlarning erta kariyesga uchrashining oldini olish uchun, ayniqsa uxlashdan oldin, shakarli oziq-ovqat va ichimliklardan saqlaning.') WHERE id = '5c0c2cd7-bbc3-4acf-aa29-a75ff9325110';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Muntazam ravishda stomatolog ko‘rigidan o‘tish'), content_uz = COALESCE(content_uz, 'Chaqaloqni birinchi tug‘ilgan kunidan oldin yoki birinchi tishi ko‘rinishi bilanoq stomatolog ko‘rigiga olib borishni rejalashtiring.') WHERE id = '5d8e7654-1e68-474f-b792-610a380b7688';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'Sovutilgan tish chiqarish halqalari'), content_uz = COALESCE(content_uz, 'Tish chiqarish halqalarini muzlatkichda saqlang. Ularni hech qachon muzlatmang, chunki ular chaqaloqning milklariga zarar yetkazadigan darajada sovuq bo‘lishi mumkin.') WHERE id = '6e21f5d7-f642-4d33-9bfc-bd32e68b561c';
UPDATE public.teething_care_tips SET title_uz = COALESCE(title_uz, 'So‘lakdan paydo bo‘ladigan toshmaning oldini olish'), content_uz = COALESCE(content_uz, 'Chaqaloqning iyagi va bo‘ynini quruq tuting. So‘lakdan paydo bo‘ladigan toshmaning oldini olish uchun yumshoq himoya kremini surting.') WHERE id = '9dc209b1-6f09-4b82-b44f-3bc06493d519';

